class DancepadVideoTabs{static instances=[];constructor(root){this.root=root;this.navItems=Array.from(root.querySelectorAll('.dan-video-tabs__nav-item'));this.videoItems=Array.from(root.querySelectorAll('.dan-video-tabs__video-item'));this.progressElements=[];this.eventHandlers=[];this.frameId=null;this.currentIndex=0;this.isInitialized=!1;if(!this.navItems.length||!this.videoItems.length){return}this.root.removeAttribute('data-flickering');this.totalItems=this.navItems.length;this.progressElements=this.ensureProgressElements();this.setupEvents();this.isInitialized=!0;this.activate(0)}ensureProgressElements(){return this.navItems.map(navItem=>{const progressBar=navItem.querySelector('.dan-video-tabs__progress-bar');if(!progressBar){return null}let progress=progressBar.querySelector('.dan-video-tabs__progress');if(!progress){progress=document.createElement('div');progress.className='dan-video-tabs__progress';progressBar.appendChild(progress)}progress.style.width='0%';return progress})}setupEvents(){this.navItems.forEach((item,index)=>{const onClick=e=>{e.preventDefault();this.activate(index)};const onKeyDown=e=>{if(e.key==='Enter'||e.key===' '||e.keyCode===13||e.keyCode===32){e.preventDefault();this.activate(index)}};item.addEventListener('click',onClick);item.addEventListener('keydown',onKeyDown);this.eventHandlers.push({element:item,type:'click',handler:onClick},{element:item,type:'keydown',handler:onKeyDown})})}clearAnimation(){if(this.frameId){cancelAnimationFrame(this.frameId);this.frameId=null}}resetProgress(){this.progressElements.forEach(progress=>{if(progress){progress.style.width='0%'}})}pauseVideo(item){const video=item?item.querySelector('video'):null;if(video&&typeof video.pause==='function'){try{video.pause()}catch(e){}}}activate(index){if(!this.navItems.length){return}this.currentIndex=index%this.navItems.length;this.clearAnimation();this.navItems.forEach((item,i)=>{item.setAttribute('data-active',i===this.currentIndex?'true':'false')});this.videoItems.forEach((item,i)=>{if(!item){return}if(i===this.currentIndex){item.setAttribute('data-active','true')}else{item.setAttribute('data-active','false');this.pauseVideo(item)}});this.resetProgress();this.animate(this.currentIndex)}animate(index){this.clearAnimation();const progress=this.progressElements[index];const videoItem=this.videoItems[index];if(!progress||!videoItem){return}const video=videoItem.querySelector('video');const iframe=videoItem.querySelector('iframe');const runAnimation=durationMs=>{const duration=durationMs>0?durationMs:0;const start=performance.now();const step=now=>{const elapsed=now-start;const total=duration||1;const ratio=duration?Math.min(elapsed/total,1):1;progress.style.width=ratio*100+'%';if(ratio>=1){this.activate((index+1)%this.navItems.length)}else{this.frameId=requestAnimationFrame(step)}};this.frameId=requestAnimationFrame(step)};const startAnimation=()=>{let durationMs=0;if(video&&typeof video.duration==='number'&&!Number.isNaN(video.duration)&&video.duration>0){durationMs=video.duration*1000}runAnimation(durationMs)};if(video){try{video.pause();video.currentTime=0}catch(e){}const playAndAnimate=()=>{try{video.play()}catch(e){}startAnimation()};if(video.readyState>=1){playAndAnimate()}else{const onLoaded=()=>{video.removeEventListener('loadedmetadata',onLoaded);playAndAnimate()};video.addEventListener('loadedmetadata',onLoaded,{once:!0})}}else if(iframe){runAnimation(0)}else{runAnimation(0)}}destroy(){this.clearAnimation();this.eventHandlers.forEach(({element,type,handler})=>{element.removeEventListener(type,handler)});this.eventHandlers=[];this.navItems.forEach(item=>{item.removeAttribute('data-active')});this.videoItems.forEach(item=>{if(!item){return}item.removeAttribute('data-active');this.pauseVideo(item)});this.progressElements.forEach(progress=>{if(progress){progress.style.width='0%'}})}static destroyAll(){DancepadVideoTabs.instances.forEach(instance=>instance.destroy());DancepadVideoTabs.instances=[]}}function dancepad_video_tabs(){const init=()=>{DancepadVideoTabs.destroyAll();document.querySelectorAll('.dan-video-tabs').forEach(root=>{const instance=new DancepadVideoTabs(root);if(instance.isInitialized){DancepadVideoTabs.instances.push(instance)}})};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init,{once:!0});return}init()}
